/**
 * @description Integration Hub REST endpoints:
 *   POST  /services/apexrest/integrationhub/v1/{EVENT_KEY}                 inbound call
 *   GET   /services/apexrest/integrationhub/v1/status/{transactionId}      result of an inbound call
 *   PATCH /services/apexrest/integrationhub/v1/callback/{transactionId}    the middleware's callback for an outbound send
 * @group Integration Hub
 */
// The Apex REST framework requires a global class with global methods.
@SuppressWarnings('PMD.AvoidGlobalModifier')
@RestResource(urlMapping='/integrationhub/v1/*')
global with sharing class IntegrationHubInboundApi {

    /**
     * @description Inbound call to an event.
     */
    @HttpPost
    global static void receive() {
        RestRequest req = RestContext.request;
        IntegrationHubInbound.Request request = new IntegrationHubInbound.Request();
        request.eventKey = rest(req).removeEnd('/');
        request.body = req.requestBody == null ? null : req.requestBody.toString();
        request.headers = req.headers;
        IntegrationHubInbound.Response r;
        try {
            r = IntegrationHubInbound.receive(request);
        } catch (Exception e) {
            r = IntegrationHubInbound.answer(500, IntegrationHubInbound.error(e.getMessage()));
        }
        write(r);
    }

    /**
     * @description Callback for an outbound transaction.
     */
    @HttpPatch
    global static void callback() {
        RestRequest req = RestContext.request;
        String path = rest(req);
        IntegrationHubInbound.Response r;
        try {
            r = path.startsWithIgnoreCase('callback/')
                ? IntegrationHubCallback.handle(path.substringAfter('/').removeEnd('/'), req.requestBody == null ? null : req.requestBody.toString())
                : IntegrationHubInbound.answer(404, IntegrationHubInbound.error('Use PATCH callback/{transactionId}.'));
        } catch (Exception e) {
            r = IntegrationHubInbound.answer(500, IntegrationHubInbound.error(e.getMessage()));
        }
        write(r);
    }

    /**
     * @description Status of an inbound call. A GET on any other path answers 405: events and callbacks exist
     * there but take POST or PATCH, so an endpoint check sees the path as found.
     */
    @HttpGet
    global static void status() {
        String path = rest(RestContext.request);
        write(path.startsWithIgnoreCase('status/')
            ? IntegrationHubCallback.status(path.substringAfter('/').removeEnd('/'))
            : IntegrationHubInbound.answer(405, IntegrationHubInbound.error(
                'Use POST {eventKey} to call an event, PATCH callback/{transactionId}, or GET status/{transactionId}.')));
    }

    private static String rest(RestRequest req) {
        String uri = req == null || req.requestURI == null ? '' : req.requestURI.substringBefore('?');
        return uri.substringAfter('/integrationhub/v1/');
    }

    private static void write(IntegrationHubInbound.Response r) {
        RestResponse res = RestContext.response;
        res.statusCode = r.statusCode;
        res.addHeader('Content-Type', 'application/json');
        if (r.replay) {
            res.addHeader('Idempotent-Replay', 'true');
        }
        res.responseBody = Blob.valueOf(JSON.serialize(r.body));
    }
}
